template <typename team_t, typename dtype_t = void*>
__device__ __forceinline__
dtype_t* get_sym_ptr(dtype_t* ptr, const int& dst_rank_idx) const {
    IS_TEAM_RAIL({
        return team_rail.rank == dst_rank_idx ? ptr : nullptr;
    })

    IS_TEAM_WORLD_LSA({
        constexpr bool kIsTeamLSA = (std::is_same_v<team_t, ncclTeamTagLsa>);

        // Team world and not accessible by symmetric pointers
        if (not is_nvlink_accessible<team_t>(dst_rank_idx))
            return nullptr;

        // Translate into NVLink rank index
        const auto dst_nvl_rank_idx = kIsTeamLSA ?
            dst_rank_idx : (dst_rank_idx - team_rail.rank * team_lsa.nRanks);

        // Local rank bypass
        // TODO(NCCL): support this
        if (dst_nvl_rank_idx == team_lsa.rank)
            return ptr;

        // Get base ptr
        const auto dst_ptr = ncclGetLsaPointer(
            nccl_window, get_sym_offset(ptr), dst_nvl_rank_idx);
        return static_cast<dtype_t*>(dst_ptr);
    });
}

// NOTES: take care of this function when `team_t` is not LSA

    if (sm_idx == 0) {
        // Use QP 0 to do barrier: signal slot `rank_idx` on every rank, then wait for every rank's slot
        const NCCLGin barrier_gin(nccl_dev_comm, gin.nccl_window, 0, NCCL_GIN_RESOURCE_SHARING_CTA);
        for (int i = thread_idx; i < kNumRanks; i += kNumThreads)
            barrier_gin.signal<team_t>(i, ncclGin_SignalInc{static_cast<ncclGinSignal_t>(rank_idx)});
        for (int i = thread_idx; i < kNumRanks; i += kNumThreads)
            barrier_gin.wait_signal<team_t, kNumTimeoutCycles>(i, rank_idx);
    }
}

} else {
    // RDMA bulk copy
    for (int i = thread_idx; i < kNumRanks; i += kNumNotifyThreads) {
        const auto src_ptr = workspace_layout.get_scaleup_expert_count_ptr<true>() + kNumExpertsPerRank * i;
        const auto dst_ptr = workspace_layout.get_scaleup_expert_count_ptr<false>() + kNumExpertsPerRank * rank_idx;
        gin.put<team_t>(dst_ptr, src_ptr, kNumExpertsPerRank * sizeof(int64_t), i);
    }
}

// This is necessary, as the waited results will rewrite the shared memory

        ptx::tma_store_1d(send_buffer_ptr, tma_buffer.get_base_ptr(), tma_buffer.get_num_bytes<false>());
    ptx::tma_store_commit();
    __syncwarp();
}

// Issue TMA NVLink stores
EP_STATIC_ASSERT(kNumTopk <= 32, "Invalid top-k selection");
const auto dst_ptr = stored_dst_slot_idx >= 0 ?
    gin.get_sym_ptr<team_t>(recv_buffer.get_token_buffer(stored_dst_slot_idx).get_base_ptr(), stored_dst_rank_idx) :
    nullptr;
if (dst_ptr != nullptr)
    ptx::tma_store_1d(dst_ptr, tma_buffer.get_base_ptr(), tma_buffer.get_num_bytes<false>());
ptx::tma_store_commit();
__syncwarp();

// Issue RDMA put
if constexpr (not kIsScaleupNVLink) {
    // Wait the send buffer store to arrive
    ptx::tma_store_wait<1>();
    __syncwarp();

    // NOTES: we should skip the NVLink accessible ranks
    if (stored_dst_slot_idx >= 0 and dst_ptr == nullptr) {
        gin.put<team_t>(recv_buffer.get_token_buffer(stored_dst_slot_idx).get_base_ptr(),
                        send_buffer_ptr, tma_buffer.get_num_bytes<false>(), stored_dst_rank_idx);
    }
    __syncwarp();

// Directly to the remote or via RDMA
const bool nvlink_bypass = gin.is_nvlink_accessible<team_t>(src_rank_idx);
layout::TokenLayout master_token_buffer = [=]() {
    // NVLink bypass
    if (nvlink_bypass) {
        auto token_buffer = recv_buffer.get_rank_buffer(kUseRankLayout ? rank_idx : src_topk_idx).get_token_buffer(src_token_idx);
        token_buffer.set_base_ptr(gin.get_sym_ptr<team_t>(token_buffer.get_base_ptr(), src_rank_idx));
        return token_buffer;
    }

    // Use RDMA
    return send_buffer.get_rank_buffer(src_rank_idx).get_token_buffer(src_token_idx);
}();

// Wait send buffer's TMA store and issue RDMA send
// NOTES: `kDoExpandedSend` mode has already issued
if (not kDoExpandedSend and not nvlink_bypass and ptx::elect_one_sync()) {
    ptx::tma_store_wait();
    const auto dst_ptr = recv_buffer.get_rank_buffer(kUseRankLayout ? rank_idx : src_topk_idx)
        .get_token_buffer(src_token_idx).get_base_ptr();
    gin.put<team_t>(dst_ptr, master_token_buffer.get_base_ptr(),
                    master_token_buffer.get_num_bytes<false>(), src_rank_idx);
}

uint64_t signalOpArg, bool hasCounter, ncclGinCounter_t counterId, bool hasDescriptor,
ncclGinDescriptorSmem* descriptor, cuda::thread_scope required, cuda::thread_scope given, uint32_t optFlags) {
using nccl::utility::loadConst;
coop.sync();
if (coop.thread_rank() == 0) {
  ncclGinGdakiGPUContext* gdaki = &((struct ncclGinGdakiGPUContext*)ctx.handle)[ctx.contextId];
  doca_gpu_dev_verbs_qp* qp = loadConst(&gdaki->gdqp) + peer;
  doca_gpu_dev_verbs_qp* companion_qp;
  ncclGinGdakiMemHandle* dstMh = (ncclGinGdakiMemHandle*)dstWin;
  ncclGinGdakiMemHandle* srcMh = (ncclGinGdakiMemHandle*)srcWin;
  uint32_t codeOpt = nccl::gin::gdaki::docaOptFlagsFromGinOptFlags(optFlags);

  doca_gpu_dev_verbs_addr raddr, laddr;
  if (hasWins) {
    raddr.addr = dstOff;
    raddr.key = loadConst(loadConst(&dstMh->rkeys) + peer);

  } else {
    doca_gpu_dev_verbs_put<resource_sharing_mode>(qp, raddr, laddr, bytes, codeOpt);
  }
} else {
  if (hasCounter) {
    doca_gpu_dev_verbs_signal_counter<DOCA_GPUNETIO_VERBS_SIGNAL_OP_ADD, resource_sharing_mode>(
      qp, sig_raddr, sig_laddr, signalOpArg, companion_qp, counter_raddr, counter_laddr, 1, codeOpt);
  } else {
    doca_gpu_dev_verbs_signal<DOCA_GPUNETIO_VERBS_SIGNAL_OP_ADD, resource_sharing_mode>(qp, sig_raddr, sig_laddr,
                                                                                        signalOpArg, codeOpt);
  }
}

}

qp_init_attr.send_dbr_mode_ext = DOCA_GPUNETIO_VERBS_SEND_DBR_MODE_EXT_VALID_DBR;
if (nqps > nqps_for_comm) {
  DOCACHECKGOTO(doca_gpu_verbs_create_qp_list_hl(&qp_init_attr, nqps - nqps_for_comm, &gdaki_ctx->self_gqp_list),
                status, out);
  for (int qp_idx = nqps_for_comm; qp_idx < nqps; qp_idx++) {
    gdaki_ctx->gqps[qp_idx] = &gdaki_ctx->self_gqp_list->qps[qp_idx - nqps_for_comm];

    DOCACHECKGOTO(doca_verbs_qp_get_qpn(gdaki_ctx->gqps[qp_idx]->qp, &qpn), status, out);
    INFO(NCCL_NET, "[%d] Created a self-loop peer QP: qp_idx=%d, qpn=%#x", rank, qp_idx, qpn);
  }
}

for (int ctx_idx = 0; ctx_idx < ncontexts; ctx_idx++) {
  int qp_idx = rank + ctx_idx * nranks;
  if (gdaki_ctx->gqps[qp_idx] == nullptr) continue;
  struct gdaki_exch_info exch_info;
  gdakiFillExchInfo(&exch_info, gdaki_ctx, gdaki_ctx->gqps[nqps_for_comm + ctx_idx]);
  NCCLCHECKGOTO(gdakiConnectQp(gdaki_ctx, gdaki_ctx->gqps[qp_idx], &exch_info), status, out);
  DOCACHECKGOTO(doca_verbs_qp_get_qpn(gdaki_ctx->gqps[qp_idx]->qp, &qpn), status, out);
  INFO(NCCL_NET, "[%d] Connected self-loop QP: qp_idx=%d, main_qpn=%#x, peer_qpn=%#x", rank, qp_idx, qpn,
       exch_info.qpn);
}

for (int qp_idx = 0; qp_idx < nqps_per_rank; qp_idx++) {
  int peer_qp_idx = nqps_for_comm + qp_idx;
  int local_qp_idx = qp_idx * nranks + rank;
  if (gdaki_ctx->gqps[local_qp_idx] == nullptr) continue;
  struct gdaki_exch_info exch_info;
  gdakiFillExchInfo(&exch_info, gdaki_ctx, gdaki_ctx->gqps[local_qp_idx]);
  NCCLCHECKGOTO(gdakiConnectQp(gdaki_ctx, gdaki_ctx->gqps[peer_qp_idx], &exch_info), status, out);
  DOCACHECKGOTO(doca_verbs_qp_get_qpn(gdaki_ctx->gqps[peer_qp_idx]->qp, &qpn), status, out);
  INFO(NCCL_NET, "[%d] Connected self-loop peer QP: qp_idx=%d, qpn=%#x, main_qpn=%#x", rank, peer_qp_idx, qpn,
       exch_info.qpn);
}

